import OpenSeadragon from 'openseadragon';
import { useEffect, useRef, type RefObject } from 'react';

/**
 * The deep-zoom engine behind the work page's reader: OpenSeadragon on the IIIF Image API. It is
 * loaded lazily (only work pages download it) and draws no chrome of its own; the reader's
 * toolbar and keyboard drive it through `controlsRef`. A spread opens two pages side by side, both
 * scaled to the same height.
 */

/** One image on the stage: its `info.json` and the canvas size (for the side-by-side layout). */
export interface StageImage {
  readonly info: string;
  readonly width: number;
  readonly height: number;
}

/** What the reader can do to the open image. */
export interface ZoomControls {
  readonly zoomBy: (factor: number) => void;
  readonly home: () => void;
  readonly rotate: () => void;
  /** Pans by a fraction of the visible area (`0.1, 0` is a tenth of the width to the right). */
  readonly pan: (x: number, y: number) => void;
  /** True when zoomed in past the fitted view, where arrow keys pan rather than turn pages. */
  readonly zoomedIn: () => boolean;
}

/** World units between the two pages of a spread (page heights are 1). */
const GUTTER = 0.01;

export function tileSourcesOf(images: readonly StageImage[]): OpenSeadragon.TileSourceSpecifier[] {
  let x = 0;
  return images.map((image) => {
    const spec = { tileSource: image.info, x, y: 0, height: 1 };
    x += image.width / image.height + GUTTER;
    return spec;
  });
}

export default function DeepZoom({
  images,
  controlsRef,
  onZoom,
  onFailed,
}: {
  readonly images: readonly StageImage[];
  readonly controlsRef: RefObject<ZoomControls | undefined>;
  /** The zoom level in percent of the image's pixels (100 = actual size). */
  readonly onZoom: (percent: number | undefined) => void;
  readonly onFailed: (failed: boolean) => void;
}) {
  const container = useRef<HTMLDivElement>(null);
  const viewer = useRef<OpenSeadragon.Viewer | undefined>(undefined);
  // The latest props, so the viewer's handlers need not be rebound.
  const latest = useRef({ images, onZoom, onFailed });
  useEffect(() => {
    latest.current = { images, onZoom, onFailed };
  });

  useEffect(() => {
    if (container.current === null) return undefined;
    const instance = OpenSeadragon({
      element: container.current,
      showNavigationControl: false,
      // The mini-map would cover too much of a phone's stage.
      showNavigator: window.matchMedia('(min-width: 768px)').matches,
      navigatorPosition: 'BOTTOM_RIGHT',
      navigatorAutoFade: false,
      // The WebGL drawer leaves the mini-map blank in Chrome; the canvas one draws it.
      navigatorDrawer: 'canvas',
      navigatorBackground: 'rgba(0, 0, 0, 0.5)',
      navigatorSizeRatio: 0.16,
      navigatorBorderColor: 'rgba(255, 255, 255, 0.25)',
      navigatorDisplayRegionColor: '#7fb7c9',
      // The image service is on another origin (CORS `*`); WebGL draws only CORS-loaded tiles.
      crossOriginPolicy: 'Anonymous',
      visibilityRatio: 0.5,
      gestureSettingsMouse: { clickToZoom: false },
      // The reader's stage takes the focus and the keys; the canvas stays out of the tab order.
      keyboardNavEnabled: false,
      tabIndex: -1,
    });
    // Image pixels per screen pixel, of the first image (both pages of a spread match).
    const track = (zoom: number) => {
      latest.current.onZoom(
        Math.round(instance.world.getItemAt(0).viewportToImageZoom(zoom) * 100),
      );
    };
    instance.addHandler('open', () => {
      latest.current.onFailed(false);
      track(instance.viewport.getZoom(true));
    });
    instance.addHandler('zoom', (event) => {
      track(event.zoom);
    });
    instance.addHandler('open-failed', () => {
      latest.current.onFailed(true);
    });
    viewer.current = instance;
    controlsRef.current = {
      zoomBy: (factor) => {
        instance.viewport.zoomBy(factor);
        instance.viewport.applyConstraints();
      },
      home: () => {
        instance.viewport.goHome();
      },
      rotate: () => {
        instance.viewport.setRotation((instance.viewport.getRotation() + 90) % 360);
      },
      pan: (x, y) => {
        const bounds = instance.viewport.getBounds();
        instance.viewport.panBy(new OpenSeadragon.Point(bounds.width * x, bounds.height * y));
        instance.viewport.applyConstraints();
      },
      zoomedIn: () => instance.viewport.getZoom() > instance.viewport.getHomeZoom() * 1.05,
    };
    return () => {
      controlsRef.current = undefined;
      instance.destroy();
      viewer.current = undefined;
    };
  }, [controlsRef]);

  const key = images.map((image) => image.info).join(' ');
  useEffect(() => {
    if (key === '') return;
    // `key` names the images: a new array with the same images keeps the view.
    latest.current.onZoom(undefined);
    viewer.current?.open(tileSourcesOf(latest.current.images));
  }, [key]);

  return <div ref={container} data-testid="deep-zoom" className="size-full" />;
}
